const menuButton=document.querySelector('.menu-toggle');
const navLinks=document.querySelector('.nav-links');
if(menuButton&&navLinks){menuButton.addEventListener('click',()=>{const open=navLinks.classList.toggle('open');menuButton.setAttribute('aria-expanded',String(open));menuButton.textContent=open?'×':'☰'});}

// Sample projects: replace titles, credits, stills, and video URLs when real work is ready.
const projects={
  'after-the-noise':{title:'After the Noise',type:'Music Video',subject:'Concept / artist to come',year:'Sample',image:'assets/music-video.webp',description:'An intimate performance-led visual built around one voice, one room, and the space between notes.'},
  'in-the-room':{title:'In the Room',type:'Live Session',subject:'Concept / artist to come',year:'Sample',image:'assets/live-session.webp',description:'A close-up look at the energy that only happens when a song is played live.'},
  'hands-at-work':{title:'Hands at Work',type:'Documentary',subject:'Concept / subject to come',year:'Sample',image:'assets/documentary.webp',description:'A quiet portrait of craft, patience, and the people behind the work.'},
  'the-long-way-home':{title:'The Long Way Home',type:'Short Film',subject:'Concept / collaborators to come',year:'Sample',image:'assets/documentary.webp',description:'A character-led short film concept told through light, place, and small decisions.'},
  'made-to-move':{title:'Made to Move',type:'Branded Content',subject:'Concept / brand to come',year:'Sample',image:'assets/music-video.webp',description:'A cinematic brand piece with rhythm, texture, and a point of view.'}
};
const detail=document.querySelector('[data-project-detail]');
if(detail){const key=new URLSearchParams(location.search).get('project')||'after-the-noise';const p=projects[key]||projects['after-the-noise'];document.title=`${p.title} — Sequence Creative`;document.querySelector('meta[name="description"]').content=`${p.type} sample project from Sequence Creative. ${p.description}`;document.querySelector('meta[property="og:title"]').content=`${p.title} — Sequence Creative`;document.querySelector('meta[property="og:description"]').content=p.description;for(const sel of ['meta[property="og:image"]','meta[name="twitter:image"]'])document.querySelector(sel).content=new URL(p.image,location.href).href;for(const [selector,value] of [['[data-title]',p.title],['[data-type]',p.type],['[data-subject]',p.subject],['[data-year]',p.year],['[data-description]',p.description]]){document.querySelectorAll(selector).forEach(el=>el.textContent=value)}const hero=document.querySelector('[data-hero-image]');hero.src=p.image;hero.alt=`Concept still for ${p.title}`;document.querySelector('[data-gallery-image]').src=p.image;document.querySelectorAll('.project-card').forEach(card=>{if(card.getAttribute('href')?.includes(`project=${key}`))card.remove()});}

const form=document.querySelector('[data-inquiry-form]');
if(form){form.addEventListener('submit',event=>{event.preventDefault();const data=new FormData(form);const subject=`Project inquiry: ${data.get('projectType')||'New project'}`;const body=[`Name: ${data.get('name')}`,`Email: ${data.get('email')}`,`Company / artist / organization: ${data.get('organization')||'—'}`,`Project type: ${data.get('projectType')}`,`Budget: ${data.get('budget')||'Not specified'}`,`Target date: ${data.get('date')||'Not specified'}`,'',String(data.get('details')||'')].join('\n');location.href=`mailto:hello@sequencecreative.com?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;form.querySelector('.form-status').textContent='Your email app should open with a draft. The studio email is a placeholder until you add your real address.';});}
